WITH flattened AS (SELECT c.id, elem.product_id, elem.price, elem.promo FROM carts c LATERAL VIEW OUTER EXPLODE(c.items) t AS elem) SELECT id, product_id, promo, AVG(product_id) OVER (PARTITION BY promo) AS promo_avg_product_id, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share_2, DENSE_RANK() OVER w_ordered AS price_dense_rank FROM flattened WHERE promo = 'BUNDLE' WINDOW w_ordered AS (ORDER BY price DESC);
